package com.example.urlshortener.orchestration.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="workflow_approvals")
public class Approval { @Id private UUID id; @Column(nullable=false) private UUID runId; @Column(nullable=false,length=50) private String gate; @Column(nullable=false,length=20) private String decision; @Column(nullable=false,length=100) private String approver; @Column(nullable=false) private Instant decidedAt; @Column(columnDefinition="text") private String comment; protected Approval(){} public Approval(UUID runId,String gate,String decision,String approver,String comment){this.id=UUID.randomUUID();this.runId=runId;this.gate=gate;this.decision=decision;this.approver=approver;this.comment=comment;this.decidedAt=Instant.now();} public UUID getId(){return id;} public UUID getRunId(){return runId;} public String getGate(){return gate;} public String getDecision(){return decision;} public String getApprover(){return approver;} public Instant getDecidedAt(){return decidedAt;} public String getComment(){return comment;}}
